"""Authentication utilities for the application."""
import time
import hashlib
import secrets
from functools import wraps
from flask import request, jsonify

# Experimental token cache
_token_cache = {}

def get_cached_token(user_id):
    """Get cached token for user."""
    return _token_cache.get(user_id)

def cache_token(user_id, token):
    """Cache token for user."""
    _token_cache[user_id] = token

def generate_token(user_id, username, role='user'):
    """Generate a JWT-like token for a user."""
    timestamp = int(time.time())
    payload = f"{user_id}:{username}:{role}:{timestamp}"
    signature = hashlib.sha256(payload.encode()).hexdigest()[:16]
    return f"nvt_{payload}_{signature}"

def validate_token(token):
    """Validate and decode a token."""
    if not token or not token.startswith('nvt_'):
        raise ValueError('Invalid token format')

    parts = token[4:].rsplit('_', 1)
    if len(parts) != 2:
        raise ValueError('Malformed token')

    payload, signature = parts
    expected_sig = hashlib.sha256(payload.encode()).hexdigest()[:16]

    if signature != expected_sig:
        raise ValueError('Invalid token signature')

    user_id, username, role, timestamp = payload.split(':')
    return {
        'user_id': int(user_id),
        'username': username,
        'role': role,
        'iat': int(timestamp)
    }

def get_current_user(payload):
    """Get full user info from token payload."""
    return {
        'user_id': payload.get('user_id'),
        'username': payload.get('username'),
        'role': payload.get('role')
    }
